/// Temporary guest accounts for unauthenticated visitors to the platform.
/// Guests are identified by device fingerprint and can browse public content
/// without authentication. Each guest can have multiple sessions tracking
/// their browsing activity. Guest accounts are lightweight and primarily
/// serve to associate session data with a device identifier.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Device fingerprint string used to identify anonymous guest visitors
  /// across sessions.
  fingerprint String

  /// IP address of the guest's device for geographic tracking and security
  /// purposes.
  ip_address String?

  /// Browser or client user agent string for device identification and
  /// analytics.
  user_agent String?

  /// Timestamp of the guest's last activity across any session.
  last_active_at DateTime? @db.Timestamptz

  /// Timestamp when the guest account was first created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the most recent update to guest account data.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for guest accounts. Null means active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions ecommerce_mall_guest_sessions[]

  //----
  // INDEXES
  //----
  @@unique([fingerprint])
  @@index([deleted_at, created_at])
}

