  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  admin ecommerce_mall_admins @relation(fields: [ecommerce_mall_admin_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_admin_id, created_at], map: "ecommerce_mall_admin_audit_logs_ecommerce_mall_admin_i_59ecfc9e")
  @@index([resource_type, resource_id])
  @@index([created_at])
}

