      },
    );
  typia.assert(initialProfile);
  // 4. Verify initial profile data
  TestValidator.equals(
    "initial shop name",
    initialProfile.name,
    initialShopName,
  );
  TestValidator.equals(
    "initial description",
    initialProfile.description,
    initialDescription,
  );
  // 5. Update shop profile with new values
