 * partial updates correctly. When only the name field is provided in the
 * request body, other fields (description, logo_uri) should remain unchanged.
 * This test ensures:
 *
 * - Partial updates work correctly - only specified fields are modified
 * - Unmodified fields are preserved and not corrupted or reset
 * - The updated_at timestamp is properly updated on partial modifications
 * - Profile snapshots are created for historical tracking
 *
 * 1. Register a new customer via POST /ecommerceMall/auth/customer/join
 * 2. Create customer connection with authentication token
 * 3. First update with initial data (name + description)
 * 4. Second update with only name field (partial update)
 * 5. Verify name is updated, description is preserved, timestamp changed
 */
export async function test_api_customer_profile_partial_update_name_only(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
