export async function test_api_cart_add_variant_new_item(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator creates a category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category =
    await generate_random_ecommerce_mall_admin_admin_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // 2. Seller registers
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Customer registers (will use their cart later)
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {});
  typia.assert(customerAuth);
  // 4. Seller creates a product with the category (use prepare function for complete data)
  const productInput = await prepare_random_ecommerce_mall_product({
    categoryId: category.id,
  });
  const product =
    await generate_random_ecommerce_mall_seller_sellers_me_products_create(
      sellerConnection,
      {
        body: productInput satisfies IEcommerceMallProduct.ICreate,
      },
    );
  typia.assert(product);
  // 5. Seller creates a product variant with price (use prepare function for complete data)
  const variantPrice = typia.random<
    number & tags.Type<"uint32"> & tags.Minimum<1000> & tags.Maximum<10000>
  >();
  const variantInput = await prepare_random_ecommerce_mall_product_variant({
    price: variantPrice,
    optionValues: [
      { key: "Size", value: "Large" },
    ] satisfies IEcommerceMallProductVariantOptionValue.ICreate[],
  });
  const variant =
    await generate_random_ecommerce_mall_seller_sellers_me_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
        body: variantInput satisfies IEcommerceMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // 6. Customer adds the variant to their cart with quantity 1
  const quantity = 1;
  const cart = await api.functional.ecommerceMall.customer.me.cart.create(
    customerConnection,
    {
      body: {
        productVariantId: variant.id,
        quantity: quantity,
      } satisfies IEcommerceMallCartItem.ICreate,
    },
  );
  typia.assert(cart);
  // 7. Validate cart creation and item addition
  TestValidator.equals("cart exists", cart.items !== null, true);
  TestValidator.equals("cart has exactly 1 item", cart.items.length, 1);
  const cartItem = cart.items[0];
  TestValidator.equals(
    "variant reference matches",
    cartItem.variant.id,
    variant.id,
  );
  TestValidator.equals("quantity equals 1", cartItem.quantity, quantity);
  TestValidator.equals(
    "variant SKU matches",
    cartItem.variant.skuCode,
    variant.skuCode,
  );
  TestValidator.equals(
    "variant price matches",
    cartItem.variant.price,
    variantPrice,
  );
  // 8. Validate subtotal calculation (quantity × unit price)
  // Variant price can be null, in which case product basePrice is used
  const unitPrice = variant.price ?? product.basePrice;
  const expectedSubtotal = quantity * unitPrice;
  TestValidator.equals(
    "subtotal is correctly calculated",
    cartItem.subtotal,
    expectedSubtotal,
  );
  // 9. Validate cart total equals single item subtotal
  TestValidator.equals(
    "cart total equals item subtotal",
    cart.total,
    expectedSubtotal,
  );
  // 10. Validate cart has valid ID and timestamps
  TestValidator.predicate("cart has valid id", cart.id.length > 0);
  TestValidator.predicate(
    "cart has valid timestamps",
    cart.createdAt !== null && cart.updatedAt !== null,
  );
}

