/**
 * Test that an authenticated customer can successfully update the quantity of a cart item.
 *
 * Validates the primary success path for the cart item quantity update operation. Verifies that when a customer updates the quantity of a cart item to a valid positive integer, the response contains the updated cart item with the correct quantity, subtotal, and timestamp.
 *
 * 1. Register a new customer account with valid credentials.
 * 2. Add a product variant to the customer's cart with initial quantity of 1.
 * 3. Verify the cart item was created successfully with the initial quantity.
 * 4. Update the cart item quantity to 5 via PUT endpoint.
 * 5. Validate response: quantity equals 5, subtotal correctly computed, updatedAt is recent.
 */
export async function test_api_cart_item_quantity_update_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  typia.assert(customer);
  // 2. Add a product variant to the cart with initial quantity of 1
  const cart = await generate_random_ecommerce_mall_customer_me_cart_create(
    customerConnection,
    {
      body: {
        quantity: 1,
      },
    },
  );
  typia.assert(cart);
  // Get the first cart item
  const cartItem = cart.items[0];
  const initialQuantity = cartItem.quantity;
  const variantPrice = cartItem.variant.price ?? cartItem.product.basePrice;
  // 3. Verify the cart item was created with initial quantity
  TestValidator.predicate("cart has items", cart.items.length > 0);
  TestValidator.equals("initial quantity is 1", initialQuantity, 1);
  // 4. Update the cart item quantity to 5
  const newQuantity = 5;
  const updatedCartItem =
    await api.functional.ecommerceMall.customer.me.cart.items.putByCartitemid(
      customerConnection,
      {
        cartItemId: cartItem.id,
        body: {
          quantity: newQuantity,
        } satisfies IEcommerceMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedCartItem);
  // 5. Validate response
  TestValidator.equals(
    "updated quantity is 5",
    updatedCartItem.quantity,
    newQuantity,
  );
  TestValidator.equals(
    "subtotal equals quantity * price",
    updatedCartItem.subtotal,
    newQuantity * variantPrice,
  );
  // Validate updatedAt is recent (within a few seconds)
  const updatedAtTime = new Date(updatedCartItem.updatedAt).getTime();
  const now = Date.now();
  TestValidator.predicate("updatedAt is recent", now - updatedAtTime < 5000);
}

