/**
 * Test seller inventory restock with positive quantity.
 *
 * Validates that a seller can successfully add inventory (restock) to a product variant
 * using a positive quantity change. Verifies the complete restock workflow including
 * seller authentication, product creation, variant creation, inventory modification,
 * and stock accumulation.
 *
 * 1. Seller registers and authenticates via seller join endpoint.
 * 2. Seller creates a product with required fields (name, description, basePrice, categoryId).
 * 3. Seller creates a product variant with unique SKU code and option values.
 * 4. Verify initial stock is 0 for the new variant.
 * 5. Restock inventory with positive quantity (100) and reason 'restock'.
 * 6. Validate inventory record contains correct quantityChange and reason.
 * 7. Restock again to verify stock accumulation works correctly.
 * 8. Validate total stock equals sum of all inventory records.
 */
export async function test_api_inventory_restock_positive_quantity(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass123!",
      href: "https://example.com/seller/register",
      referrer: "https://example.com",
    },
  });
  // 2. Create a product
  const product =
    await generate_random_ecommerce_mall_seller_sellers_me_products_create(
      sellerConnection,
      {},
    );
  typia.assert(product);
  // 3. Create a product variant
  const variant =
    await generate_random_ecommerce_mall_seller_sellers_me_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 4. Verify initial stock is 0
  TestValidator.equals("initial stock should be 0", variant.quantity, 0);
  // 5. Restock inventory with positive quantity (100) and reason 'restock'
  const restockQuantity = 100;
  const inventoryRecord =
    await generate_random_ecommerce_mall_seller_variants_inventory_restock(
      sellerConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantityChange: restockQuantity,
          reason: "restock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 6. Validate inventory record
  TestValidator.equals(
    "quantityChange should be 100",
    inventoryRecord.quantityChange,
    restockQuantity,
  );
  TestValidator.equals(
    "reason should be restock",
    inventoryRecord.reason,
    "restock",
  );
  TestValidator.predicate(
    "id should be valid UUID",
    /^[0-9a-f-]{36}$/i.test(inventoryRecord.id),
  );
  // 7. Restock again with additional quantity to verify accumulation
  const additionalQuantity = 50;
  const secondRecord =
    await generate_random_ecommerce_mall_seller_variants_inventory_restock(
      sellerConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantityChange: additionalQuantity,
          reason: "restock",
        },
      },
    );
  typia.assert(secondRecord);
  // 8. Validate second record
  TestValidator.equals(
    "second quantityChange should be 50",
    secondRecord.quantityChange,
    additionalQuantity,
  );
  TestValidator.equals(
    "second reason should be restock",
    secondRecord.reason,
    "restock",
  );
  // Verify total stock accumulation
  const totalExpectedStock = restockQuantity + additionalQuantity;
  TestValidator.equals(
    "total stock should be 150",
    variant.quantity + additionalQuantity,
    totalExpectedStock,
  );
}

