  const restockRecord =
    await generate_random_ecommerce_mall_seller_variants_inventory_create(
      firstSellerConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantityChange: 100 satisfies number & tags.Type<"int32">,
          reason: "restock",
        },
      },
    );
