export async function test_api_review_creation_for_delivered_order_item(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  typia.assert(customer);
  // 2. Create a shipping address
  const address =
    await generate_random_ecommerce_mall_customer_customers_me_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 3. Create an order
  const order =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customerConnection,
      {
        body: {
          shippingAddressId: address.id,
        },
      },
    );
  typia.assert(order);
  // 4. Extract order item ID from the created order
  const orderItem = order.orderItems[0];
  TestValidator.equals("order has items", order.orderItems.length > 0, true);
  // 5. Simulate delivery by confirming shipment if exists
  if (order.shipments && order.shipments.length > 0) {
    const shipment = order.shipments[0];
    await api.functional.ecommerceMall.customer.customers.me.orders.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
      },
    );
  }
  // 6. Create review for the order item with rating=5
  const reviewRating = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
  >();
  const reviewContent = "Excellent product! Highly recommend.";
  const review =
    await api.functional.ecommerceMall.customer.customers.me.orders.items.review.create(
      customerConnection,
      {
        itemId: orderItem.id,
        body: {
          rating: reviewRating,
          content: reviewContent,
        } satisfies IEcommerceMallReview.ICreate,
      },
    );
  typia.assert(review);
  // 7. Validate review response
  TestValidator.equals("rating matches request", review.rating, reviewRating);
  TestValidator.equals(
    "content matches request",
    review.content,
    reviewContent,
  );
  TestValidator.equals("customer matches", review.customer.id, customer.id);
  TestValidator.equals("orderItem matches", review.orderItem.id, orderItem.id);
  TestValidator.predicate(
    "createdAt is set",
    review.createdAt !== undefined && review.createdAt !== null,
  );
  TestValidator.predicate(
    "updatedAt is set",
    review.updatedAt !== undefined && review.updatedAt !== null,
  );
}

