/**
 * Test successful delivery confirmation workflow for a customer receiving their package.
 *
 * Validates the complete order fulfillment flow including customer registration, seller approval, product creation, order placement, seller shipment, and customer delivery confirmation. Ensures that when a customer confirms receipt of their package, the order items transition from 'shipped' to 'delivered' status correctly.
 *
 * **Test Flow:**
 * 1. Register and authenticate a customer account
 * 2. Register and authenticate a seller account (must be approved to create products)
 * 3. Create shipping address for the customer
 * 4. Seller creates a product with inventory (via product creation API)
 * 5. Customer adds product to cart and creates an order
 * 6. Seller ships the order items, creating a shipment with items in 'shipped' status
 * 7. Customer confirms delivery via the confirm-delivery endpoint
 * 8. Verify all order items in the shipment have 'delivered' status
 * 9. Verify shipment details reflect the delivered state
 *
 * **Expected Results:**
 * - HTTP 200 OK with updated shipment response
 * - All order items in shipment have status='delivered'
 * - Delivery confirmation timestamp recorded
 */
export async function test_api_shipment_delivery_confirmation_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  typia.assert(customer);
  // 2. Register and authenticate seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  typia.assert(seller);
  // 3. Create shipping address for customer
  const address =
    await api.functional.ecommerceMall.customer.customers.me.addresses.create(
      customerConnection,
      {
        body: {
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          street_address: "123 Test Street",
          city: "Test City",
          state: "Test State",
          postal_code: "12345",
          country: "Test Country",
          is_default: true,
        } satisfies IEcommerceMallShippingAddress.ICreate,
      },
    );
  typia.assert(address);
  // 4. Create order with items using the generate helper function
  const order =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customerConnection,
      {
        body: {
          shippingAddressId: address.id,
        },
      },
    );
  typia.assert(order);
  // 5. Seller ships the order items - get the first order item
  const orderItem = order.orderItems[0];
  const shipment =
    await generate_random_ecommerce_mall_seller_sellers_me_orders_items_ship_create(
      sellerConnection,
      {
        params: {
          itemId: orderItem.id,
        },
        body: {
          orderId: order.id,
          carrier: "DHL",
          trackingNumber: "1234567890",
          itemIds: [orderItem.id],
        },
      },
    );
  typia.assert(shipment);
  // 6. Customer confirms delivery
  const confirmedShipment =
    await api.functional.ecommerceMall.customer.customers.me.orders.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  // 7. Verify all order items in shipment have 'delivered' status
  for (const item of confirmedShipment.shipmentItems) {
    TestValidator.equals("item status is delivered", item.status, "delivered");
  }
}

