interface ICancellationRequestWithId extends IEcommerceMallCancellationRequest {
  id: string;
  status: string;
  created_at: string;
  updated_at: string;
}

export async function test_api_cancellation_request_retrieval_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates product category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category =
    await generate_random_ecommerce_mall_admin_admin_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // 2. Seller registers and creates product
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product =
    await generate_random_ecommerce_mall_seller_sellers_me_products_create(
      sellerConnection,
      {
        body: {
          categoryId: category.id,
        },
      },
    );
  typia.assert(product);
  // 3. Customer registers and creates shipping address
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const address =
    await generate_random_ecommerce_mall_customer_customers_me_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 4. Get product variant - will be added to cart by prepare_random_ecommerce_mall_order
  const variant = product.variants[0];
  if (!variant) {
    throw new Error("Product has no variants available");
  }
  // 5. Customer creates order - internally handles cart population
  const order =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customerConnection,
      {
        body: {
          shippingAddressId: address.id,
        },
      },
    );
  typia.assert(order);
  // 6. Get order item and submit cancellation request
  const orderItem = order.orderItems[0];
  if (!orderItem) {
    throw new Error("Order has no items");
  }
  const cancellation =
    await generate_random_ecommerce_mall_customer_customers_me_orders_items_cancel_create(
      customerConnection,
      {
        params: {
          itemId: orderItem.id,
        },
      },
    );
  typia.assert(cancellation);
  // 7. Seller retrieves cancellation request details
  const cancellationResponseRaw =
    await api.functional.ecommerceMall.seller.sellers.me.cancellation_requests.at(
      sellerConnection,
      {
        requestId: (cancellation as ICancellationRequestWithId).id,
      },
    );
  typia.assert(cancellationResponseRaw);
  const cancellationResponse =
    cancellationResponseRaw as ICancellationRequestWithId;
  // 8. Validate response contains all required fields
  TestValidator.equals(
    "cancellation request id matches",
    (cancellation as ICancellationRequestWithId).id,
    cancellationResponse.id,
  );
  TestValidator.equals(
    "reason is preserved",
    cancellation.reason,
    cancellationResponse.reason,
  );
  TestValidator.predicate(
    "status is pending",
    cancellationResponse.status === "pending",
  );
  TestValidator.predicate(
    "has created_at timestamp",
    !!cancellationResponse.created_at,
  );
  TestValidator.predicate(
    "has updated_at timestamp",
    !!cancellationResponse.updated_at,
  );
}

