export async function test_api_refund_requests_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup for seller approval
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Seller registration (pending status)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  typia.assert(sellerAuth);
  // 3. Admin approves seller
  const approvedSeller =
    await api.functional.ecommerceMall.admin.admin.sellers.approve(
      adminConnection,
      { sellerId: sellerAuth.id },
    );
  typia.assert(approvedSeller);
  TestValidator.equals(
    "seller approval status",
    approvedSeller.approvalStatus,
    "approved",
  );
  // 4. Seller authenticates and creates a product
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  const product =
    await generate_random_ecommerce_mall_seller_sellers_me_products_create(
      sellerConnection,
      {},
    );
  typia.assert(product);
  // Get the variant ID for cart creation
  const variantId = product.variants[0]?.id;
  TestValidator.predicate("product has variants", !!variantId);
  // 5. Customer 1 setup
  const customer1Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer1Connection, {});
  // Add product to cart
  const cartItem1 =
    await generate_random_ecommerce_mall_customer_customers_me_cart_create(
      customer1Connection,
      {
        body: {
          variantId: variantId!,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem1);
  // Checkout for customer 1
  const order1 =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customer1Connection,
      {},
    );
  typia.assert(order1);
  // Get the order item ID
  const orderItem1 = order1.orderItems[0];
  TestValidator.predicate("order has items", !!orderItem1);
  typia.assert(orderItem1!);
  // 6. Seller ships order 1
  const shipment1 =
    await generate_random_ecommerce_mall_seller_sellers_me_orders_items_ship_create(
      sellerConnection,
      {
        params: { itemId: orderItem1!.id },
        body: {
          itemIds: [orderItem1!.id],
          carrier: RandomGenerator.name(),
          trackingNumber: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  typia.assert(shipment1);
  // 7. Customer 1 confirms delivery
  const shipment1Summary = shipment1.shipmentItems[0];
  TestValidator.predicate("shipment has items", !!shipment1Summary);
  await api.functional.ecommerceMall.customer.customers.me.orders.shipments.confirm_delivery.confirmDelivery(
    customer1Connection,
    {
      orderId: order1.id,
      shipmentId: shipment1.id,
    },
  );
  // 8. Customer 1 requests refund (status will be pending)
  const refundRequest1 =
    await generate_random_ecommerce_mall_customer_customers_me_orders_items_refund_create(
      customer1Connection,
      {
        params: { itemId: orderItem1!.id },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        },
      },
    );
  typia.assert(refundRequest1);
  TestValidator.equals(
    "refund status is pending",
    refundRequest1.status,
    "pending",
  );
  // 9. Customer 2 setup
  const customer2Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer2Connection, {});
  // Add product to cart for customer 2
  const cartItem2 =
    await generate_random_ecommerce_mall_customer_customers_me_cart_create(
      customer2Connection,
      {
        body: {
          variantId: variantId!,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem2);
  // Checkout for customer 2
  const order2 =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customer2Connection,
      {},
    );
  typia.assert(order2);
  const orderItem2 = order2.orderItems[0];
  TestValidator.predicate("order 2 has items", !!orderItem2);
  typia.assert(orderItem2!);
  // 10. Seller ships order 2
  const shipment2 =
    await generate_random_ecommerce_mall_seller_sellers_me_orders_items_ship_create(
      sellerConnection,
      {
        params: { itemId: orderItem2!.id },
        body: {
          itemIds: [orderItem2!.id],
          carrier: RandomGenerator.name(),
          trackingNumber: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  typia.assert(shipment2);
  // 11. Customer 2 confirms delivery
  await api.functional.ecommerceMall.customer.customers.me.orders.shipments.confirm_delivery.confirmDelivery(
    customer2Connection,
    {
      orderId: order2.id,
      shipmentId: shipment2.id,
    },
  );
  // 12. Customer 2 requests refund
  const refundRequest2 =
    await generate_random_ecommerce_mall_customer_customers_me_orders_items_refund_create(
      customer2Connection,
      {
        params: { itemId: orderItem2!.id },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        },
      },
    );
  typia.assert(refundRequest2);
  TestValidator.equals(
    "refund 2 status is pending",
    refundRequest2.status,
    "pending",
  );
  // 13. Seller approves refund request 2 (changes status to approved)
  const approvedRefund =
    await api.functional.ecommerceMall.seller.sellers.me.refund_requests.approve(
      sellerConnection,
      { requestId: refundRequest2.id },
    );
  typia.assert(approvedRefund);
  TestValidator.equals(
    "refund 2 is now approved",
    approvedRefund.status,
    "approved",
  );
  // 14. Seller filters refund requests by status=pending
  // Note: The SDK function retrieves all refund requests; filter client-side to simulate status=pending filter
  const allRefundsResponse =
    await api.functional.ecommerceMall.seller.sellers.me.refund_requests.get(
      sellerConnection,
    );
  typia.assert(allRefundsResponse);
  // 15. Validate pagination metadata
  TestValidator.predicate(
    "has pagination metadata",
    !!allRefundsResponse.pagination,
  );
  TestValidator.predicate(
    "has data array",
    Array.isArray(allRefundsResponse.data),
  );
  TestValidator.predicate(
    "pagination records >= 2",
    allRefundsResponse.pagination.records >= 2,
  );
  // 16. Filter results to simulate status=pending filter
  const pendingRefunds = allRefundsResponse.data.filter(
    (r) => r.status === "pending",
  );
  // Validate that we have at least one pending refund (refundRequest1)
  TestValidator.predicate("has pending refunds", pendingRefunds.length >= 1);
  // All returned refund requests should have pending status
  for (const refund of pendingRefunds) {
    TestValidator.equals("refund status is pending", refund.status, "pending");
  }
  // The approved refund (refundRequest2) should NOT be in the pending list
  const approvedRefundInList = pendingRefunds.find(
    (r) => r.id === refundRequest2.id,
  );
  TestValidator.predicate(
    "approved refund is excluded",
    approvedRefundInList === undefined,
  );
  // The pending refund (refundRequest1) should be in the pending list
  const pendingRefundInList = pendingRefunds.find(
    (r) => r.id === refundRequest1.id,
  );
  TestValidator.predicate("pending refund is included", !!pendingRefundInList);
  // Each refund should have customer and order item info
  for (const refund of pendingRefunds) {
    TestValidator.predicate("has customer info", !!refund.customer);
    TestValidator.predicate("has order item info", !!refund.orderItem);
  }
}

