export async function test_api_admin_orders_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallAdmin.ILogin,
  });
  // 2. Create seller for product
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuth);
  // 3. Create product with inventory
  const product =
    await api.functional.ecommerceMall.seller.sellers.me.products.create(
      sellerConnection,
      {
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.content({ paragraphs: 2 }),
          basePrice: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          categoryId: typia.random<string & tags.Format<"uuid">>(),
        } satisfies IEcommerceMallProduct.ICreate,
      },
    );
  typia.assert(product);
  // Get variant from product
  const variant = product.variants[0];
  typia.assert(variant);
  // Add inventory to variant
  await api.functional.ecommerceMall.seller.sellers.me.variants._inventory.add(
    sellerConnection,
    {
      variantId: variant.id,
      body: {
        quantityChange: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<10>
        >(),
        reason: "Initial stock for testing",
      } satisfies IEcommerceMallInventoryRecord.ICreate,
    },
  );
  // 4. Create multiple customers and place orders
  const orderCount = 3;
  const orders: IEcommerceMallOrder[] = [];
  for (let i = 0; i < orderCount; i++) {
    // Create customer
    const customerConnection: api.IConnection = { host: connection.host };
    await authorize_customer_join(customerConnection, {});
    // Create shipping address
    const address =
      await api.functional.ecommerceMall.customer.customers.me.addresses.create(
        customerConnection,
        {
          body: {
            recipient_name: RandomGenerator.name(),
            phone: RandomGenerator.mobile(),
            street_address: `${RandomGenerator.alphabets(5)} Street`,
            city: "Test City",
            state: "Test State",
            postal_code: "12345",
            country: "Test Country",
          } satisfies IEcommerceMallShippingAddress.ICreate,
        },
      );
    typia.assert(address);
    // Add item to cart
    await api.functional.ecommerceMall.customer.customers.me.cart.create(
      customerConnection,
      {
        body: {
          variantId: variant.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<3>
          >(),
        } satisfies IEcommerceMallCart.ICreate,
      },
    );
    // Create order (status will be 'paid' after successful checkout)
    const order =
      await api.functional.ecommerceMall.customer.customers.me.orders.create(
        customerConnection,
        {
          body: {
            shippingAddressId: address.id,
          } satisfies IEcommerceMallOrder.ICreate,
        },
      );
    typia.assert(order);
    orders.push(order);
  }
  // 5. List orders as admin
  const ordersPage =
    await api.functional.ecommerceMall.admin.admin.orders.list(adminConnection);
  typia.assert(ordersPage);
  // 6. Validate orders have correct structure and 'paid' status
  TestValidator.equals(
    "has created orders",
    ordersPage.data.length,
    orderCount,
  );
  for (const order of ordersPage.data) {
    TestValidator.equals("status is paid", order.status, "paid");
    TestValidator.predicate("has order id", order.id !== null);
    TestValidator.predicate("has order number", order.order_number !== null);
    TestValidator.predicate("has customer info", order.customer !== null);
    TestValidator.predicate("has total amount", order.total_amount !== null);
  }
  // 7. Validate pagination metadata
  TestValidator.predicate("pagination exists", ordersPage.pagination !== null);
  TestValidator.equals("current page", ordersPage.pagination.current, 1);
  TestValidator.predicate("has limit", ordersPage.pagination.limit !== null);
  TestValidator.equals(
    "records count",
    ordersPage.pagination.records,
    orderCount,
  );
}

