 *
 * Validates the complete shipment tracking update flow including seller registration, order creation by customer, shipment creation, and subsequent tracking information modification. Ensures that when a seller updates their own shipment's carrier and tracking number, the changes are properly persisted with refreshed timestamps.
 *
 * The test flow:
 * 1. Seller registers and authenticates (assumed approved for testing)
 * 2. Customer registers and authenticates
 * 3. Customer creates a shipping address for order delivery
 * 4. Order is placed with paid items (using generation function)
 * 5. Seller creates a shipment for the order items
 * 6. Seller updates the shipment with new carrier and tracking number
 * 7. Validates the shipment has updated carrier ('FedEx'), tracking number ('TRACK123456'), and refreshed timestamp
 *
 * Key validations ensure the update operation only modifies tracking fields while preserving ownership and item associations.
 */
export async function test_api_shipment_tracking_update_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // Login as approved seller
  const sellerLoginConnection: api.IConnection = { host: connection.host };
  const sellerLogin = await authorize_seller_login(sellerLoginConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerLogin);
  // 2. Register and authenticate customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customerAuth);
  // Login as customer
  const customerLoginConnection: api.IConnection = { host: connection.host };
  const customerLogin = await authorize_customer_login(
    customerLoginConnection,
    {
      body: {
        email: customerEmail,
        password: customerPassword,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      },
    },
  );
  typia.assert(customerLogin);
  // 3. Create shipping address for customer
  const address =
    await generate_random_ecommerce_mall_customer_customers_me_addresses_create(
      customerLoginConnection,
      {},
    );
  typia.assert(address);
  // 4. Create order with paid items
  const order =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customerLoginConnection,
      {
        body: {
          shippingAddressId: address.id,
        },
      },
    );
  typia.assert(order);
  // Capture order items for shipment
  const orderItemIds = order.orderItems.map((item) => item.id);
  TestValidator.equals("order has items", orderItemIds.length > 0, true);
  // 5. Create shipment for the order items
  const initialCarrier = "DHL";
  const initialTracking =
    "DHL" + RandomGenerator.alphaNumeric(10).toUpperCase();
  const shipment = await generate_random_ecommerce_mall_seller_shipments_create(
    sellerLoginConnection,
    {
      body: {
        orderId: order.id,
        carrier: initialCarrier,
        trackingNumber: initialTracking,
        itemIds: orderItemIds,
      } satisfies IEcommerceMallShipment.ICreate,
    },
  );
  typia.assert(shipment);
