export async function test_api_cancellation_request_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin account for category creation
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create category for product assignment
  const category =
    await generate_random_ecommerce_mall_admin_admin_categories_create(
      adminConnection,
      {},
    );
  // 3. Create seller account and login
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      password: sellerPassword,
    },
  });
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerAuth.email,
      password: sellerPassword,
      href: "https://example.com",
      referrer: "https://example.com",
    },
  });
  // 4. Seller creates product with category
  const product =
    await generate_random_ecommerce_mall_seller_sellers_me_products_create(
      sellerConnection,
      {
        body: {
          categoryId: category.id,
          name: "Test Product for Cancellation",
          description: "Test product description",
          basePrice: 10000,
        },
      },
    );
  // Get product variant ID (use first variant if available)
  const variantId = product.variants[0]?.id;
  if (!variantId) {
    throw new Error("Product has no variants");
  }
  // 5. Create customer account and authenticate
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 6. Customer creates shipping address
  await generate_random_ecommerce_mall_customer_customers_me_addresses_create(
    customerConnection,
    {},
  );
  // 7. Customer adds product to cart
  await generate_random_ecommerce_mall_customer_customers_me_cart_create(
    customerConnection,
    {
      body: {
        variantId: variantId,
        quantity: 1,
      },
    },
  );
  // 8. Customer creates order
  const order =
    await generate_random_ecommerce_mall_customer_customers_me_orders_create(
      customerConnection,
      {},
    );
  // Get the first order item ID
  const orderItemId = order.orderItems[0]?.id;
  if (!orderItemId) {
    throw new Error("Order has no items");
  }
  // 9. Attempt to get cancellation request - should return 404
  await TestValidator.httpError(
    "cancellation request not found (404)",
    404,
    async () =>
      await api.functional.ecommerceMall.customer.customers.me.orders.items.cancellation.at(
        customerConnection,
        {
          itemId: orderItemId,
        },
      ),
  );
}

