export async function test_api_cancellation_snapshot_seller_view_own_request(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates a product category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  const category =
    await api.functional.ecommerceMall.admin.admin.categories.create(
      adminConnection,
      {
        body: {
          name: RandomGenerator.paragraph({ sentences: 1 }),
          description: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IEcommerceMallCategory.ICreate,
      },
    );
  typia.assert(category);
  // 2. Seller registers (starts with pending status)
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // 3. Customer registers and authenticates
  const customerConnection: api.IConnection = { host: connection.host };
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customerAuth);
  // 4. Seller logs in (seller needs to be approved to create products)
  const approvedSellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(approvedSellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallSeller.ILogin,
  });
  // 5. Seller creates a product with the category
  const product =
    await api.functional.ecommerceMall.seller.sellers.me.products.create(
      approvedSellerConnection,
      {
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.paragraph({ sentences: 5 }),
          basePrice: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          categoryId: category.id,
        } satisfies IEcommerceMallProduct.ICreate,
      },
    );
  typia.assert(product);
  // 6. Customer adds shipping address
  const address =
    await api.functional.ecommerceMall.customer.customers.me.addresses.create(
      customerConnection,
      {
        body: {
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          street_address: `${RandomGenerator.alphabets(5)} Street`,
          city: "Test City",
          state: "Test State",
          postal_code: "12345",
          country: "Test Country",
          is_default: true,
        } satisfies IEcommerceMallShippingAddress.ICreate,
      },
    );
  typia.assert(address);
  // 7. Customer creates order from cart
  const order =
    await api.functional.ecommerceMall.customer.customers.me.orders.create(
      customerConnection,
      {
        body: {
          shippingAddressId: address.id,
        } satisfies IEcommerceMallOrder.ICreate,
      },
    );
  typia.assert(order);
  // Get the first order item
  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  // 8. Customer submits cancellation request
  const cancellationRequest =
    typia.assert<IEcommerceMallCancellationRequest & { id: string }>(
      await api.functional.ecommerceMall.customer.customers.me.orders.items.cancel.create(
        customerConnection,
        {
          itemId: orderItem.id,
          body: {
            reason: "Changed my mind",
          } satisfies IEcommerceMallCancellationRequest.ICreate,
        },
      ),
    );
  // 9. Seller approves the cancellation request (creates snapshot)
  const approvedRequest =
    await api.functional.ecommerceMall.seller.sellers.me.cancellation_requests.approve(
      approvedSellerConnection,
      {
        requestId: cancellationRequest.id,
      },
    );
  typia.assert(approvedRequest);
  // 10. Seller retrieves cancellation request snapshots
  const snapshotsResponse =
    await api.functional.ecommerceMall.seller.cancellation_requests.snapshots.index(
      approvedSellerConnection,
      {
        requestId: cancellationRequest.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IEcommerceMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotsResponse);
  // Validations
  TestValidator.equals(
    "has pagination data",
    snapshotsResponse.pagination !== undefined,
    true,
  );
  TestValidator.equals(
    "has snapshots data",
    snapshotsResponse.data !== undefined,
    true,
  );
  TestValidator.predicate(
    "has at least one snapshot",
    snapshotsResponse.data.length > 0,
  );
  const snapshot = snapshotsResponse.data[0];
  TestValidator.equals(
    "snapshot reason matches",
    snapshot.reason,
    "Changed my mind",
  );
  TestValidator.equals(
    "snapshot status is approved",
    snapshot.status,
    "approved",
  );
  // Verify pagination structure
  TestValidator.predicate(
    "pagination has current page",
    snapshotsResponse.pagination.current > 0,
  );
  TestValidator.predicate(
    "pagination has limit",
    snapshotsResponse.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination has records",
    snapshotsResponse.pagination.records > 0,
  );
}

