  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  // 7. Request refund for the delivered order item
  const refundRequest =
    await generate_random_ecommerce_mall_customer_customers_me_orders_items_refund_create(
      customerConnection,
      {
        params: {
          itemId: orderItem.id,
        },
