        } satisfies IEcommerceMallOrder.ICreate,
      },
    );
  typia.assert(order);
  // Get an order item ID for creating refund request
  const orderItem = order.orderItems[0];
  const orderItemId = orderItem.id;
  // 4. Create refund request (generation function handles the delivery status internally)
  const refundRequest =
    await generate_random_ecommerce_mall_customer_customers_me_orders_items_refund_create(
      customerConnection,
      {
        params: {
          itemId: orderItemId,
        },
      },
    );
  typia.assert(refundRequest);
  // 5. Attempt to retrieve a non-existent snapshot using a random UUID
  const nonExistentSnapshotId = typia.random<string & tags.Format<"uuid">>();
  // 6. Validate 404 response for non-existent snapshot
  await TestValidator.httpError(
    "non-existent snapshot returns 404 Not Found",
    404,
    async () => {
      await api.functional.ecommerceMall.customer.refund_requests.snapshots.at(
        customerConnection,
        {
          requestId: refundRequest.id,
          snapshotId: nonExistentSnapshotId,
        },
      );
    },
  );
}

