  TestValidator.equals(
    "rejectionReason should be null for approved seller",
    rejectionReason.rejectionReason,
    null,
  );
  TestValidator.equals(
    "rejectedAt should be null for approved seller",
    rejectionReason.rejectedAt,
    null,
  );
}

