  const skip = (page - 1) * limit;
  const whereInput: Prisma.ecommerce_mall_super_admin_audit_logsWhereInput = {
    ...(props.body.action !== undefined && { action: props.body.action }),
    ...(props.body.target_type !== undefined && {
