import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAdminAdminCustomersCustomerIdBan(props: {
  admin: AdminPayload;
  customerId: string & tags.Format<"uuid">;
}): Promise<IEcommerceMallCustomer> {
  // 1. Verify customer exists and check ban status
  const existing = await MyGlobal.prisma.ecommerce_mall_customers.findUnique({
    where: { id: props.customerId },
    select: { id: true, deleted_at: true },
  });
  // 2. Not found → 404
  if (existing === null) {
    throw new HttpException("Customer not found", 404);
  }
  // 3. Already banned → 400
  if (existing.deleted_at !== null) {
    throw new HttpException("Customer is already banned", 400);
  }
  // 4. Ban the customer by setting deleted_at timestamp
  await MyGlobal.prisma.ecommerce_mall_customers.update({
    where: { id: props.customerId },
    data: {
      deleted_at: new Date(),
      updated_at: new Date(),
    },
  });
  // 5. Invalidate all active sessions for this customer
  await MyGlobal.prisma.ecommerce_mall_customer_sessions.deleteMany({
    where: { ecommerce_mall_customer_id: props.customerId },
  });
  // 6. Re-fetch the updated customer with full relations
  const record =
    await MyGlobal.prisma.ecommerce_mall_customers.findUniqueOrThrow({
      where: { id: props.customerId },
      ...EcommerceMallCustomerTransformer.select(),
    });
  // 7. Transform and return the banned customer
  return await EcommerceMallCustomerTransformer.transform(record);
}

