@Controller("/ecommerceMall/products/:productId/reviews")
export class EcommercemallProductsReviewsController {
  /**
   * Retrieves a paginated list of reviews for a specific product.
   *
   * This endpoint is publicly accessible and does not require authentication. Reviews are returned sorted by creation date with the most recent reviews appearing first. Each review includes the reviewer's display name (derived from their customer profile), star rating, text content, and creation timestamp.
   *
   * Only active (non-deleted) reviews are returned. If the product has no reviews or has been deleted, an empty list is returned with pagination metadata showing zero total results.
   *
   * ## Pagination
   *
   * Results are paginated using offset-based pagination with configurable page number and page size. The response includes pagination metadata such as total review count and total number of pages.
   *
   * ## Error Scenarios
   *
   * - If the product does not exist, the system returns a 404 error with a message indicating the product was not found.
   * - Invalid pagination parameters (negative page numbers or page sizes exceeding the maximum) result in validation errors.
   *
   * @param connection
   * @param productId Unique identifier of the product (UUID format).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Query ecommerce_mall_reviews table filtered by product ID and null deleted_at (active reviews only).
   *
   * Join with ecommerce_mall_customers to get customer id, then left join with ecommerce_mall_customer_profiles to retrieve display_name for reviewer attribution.
   *
   * Apply sorting: ORDER BY created_at DESC (newest first).
   *
   * Implement pagination with page number and limit parameters. Return total count for pagination metadata.
   *
   * Validate that productId exists in ecommerce_mall_products table. If product not found, throw 404 error.
   *
   * Return reviews even if product is deleted (soft-deleted products retain their reviews per business requirements).
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async getByProductid(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
  ): Promise<IPageIEcommerceMallReview.ISummary> {
    try {
      return await getEcommerceMallProductsProductIdReviews({
        productId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves a paginated list of reviews for a specific product.
   *
   * Reviews are sorted by creation date with the most recent reviews appearing first. Only active (non-deleted) reviews are included in the results. Each review includes the customer display name, star rating, and optional text content. This endpoint is used to display product reviews on the product detail page, helping customers make informed purchasing decisions based on verified purchase experiences from other customers.
   *
   * **Sorting**: Reviews are sorted by creation timestamp in descending order (newest first).
   *
   * **Filtering**: Optional filters can be applied to narrow results by rating value.
   *
   * **Pagination**: Results are paginated with configurable page size and cursor-based navigation.
   *
   * @param connection
   * @param productId Unique identifier of the product to retrieve reviews for.
   * @param body Search criteria including pagination parameters (cursor, limit) and optional rating filter.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Query the ecommerce_mall_reviews table filtering by ecommerce_mall_product_id matching the path parameter.
   *
   * Apply WHERE deleted_at IS NULL to exclude soft-deleted reviews.
   *
   * Apply WHERE rating = {rating} if rating filter is provided in request body.
   *
   * Join with ecommerce_mall_customers and ecommerce_mall_customer_profiles to retrieve customer display names.
   *
   * Sort results by created_at DESC for newest-first ordering.
   *
   * Apply cursor-based pagination using created_at and id as cursor fields for stable sorting.
   *
   * Return paginated results with summary data: review id, customer display name, rating, content preview, and created timestamp.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IEcommerceMallReview.IRequest,
  ): Promise<IPageIEcommerceMallReview.ISummary> {
    try {
      return await patchEcommerceMallProductsProductIdReviews({
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves a single product review by its unique identifier.
   *
   * This endpoint returns a specific review for a product, including the customer who wrote it, the star rating, text content, and timestamps. Reviews must not be soft-deleted to be accessible through this endpoint.
   *
   * **Public Access**: This endpoint is accessible to all users including guests, as reviews are displayed on the product detail page to help prospective buyers make informed decisions.
   *
   * **Soft Delete Handling**: Reviews that have been deleted by customers are hidden from public display. Only active reviews (where deleted_at is null) are returned. Attempting to access a deleted review returns a 404 Not Found response.
   *
   * **Review-Product Validation**: The review must belong to the specified product. If the review exists but belongs to a different product, the system returns 404 to prevent enumeration attacks.
   *
   * **Relationships**: The response includes the customer identifier and links to the verified purchase through the associated order item.
   *
   * @param connection
   * @param productId Unique identifier of the product this review belongs to.
   * @param reviewId Unique identifier of the review to retrieve.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Query the ecommerce_mall_reviews table filtering by id = :reviewId AND ecommerce_mall_product_id = :productId AND deleted_at IS NULL.
   *
   * If no matching active review exists, return HTTP 404 with error message "Review not found".
   *
   * The response should include:
   * - Review ID (UUID)
   * - Customer ID who wrote the review
   * - Rating (1-5 stars)
   * - Text content (nullable)
   * - Created timestamp
   * - Updated timestamp
   *
   * Do NOT expose soft-delete timestamp or internal IDs in the response.
   *
   * Join with ecommerce_mall_customers table to verify the customer exists (in case of orphaned reviews after customer deletion), but handle gracefully if customer is deleted.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":reviewId")
  public async getByProductidAndReviewid(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedParam("reviewId")
    reviewId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceMallReview> {
    try {
      return await getEcommerceMallProductsProductIdReviewsReviewId({
        productId,
        reviewId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

